{
  "faction": {
    "$meta": {
      "extensible": false,
      "required": ["prince_faction", "second_prince_faction"]
    },

    "prince_faction": {
      "$meta": {"extensible": false, "required": ["influence", "military_strength", "reputation_prestige"]},
      "influence": [
        90,
        "【太子党影响力】范围[0, 200]。当太子做出重大贡献、民心支持时增加；遭遇挫败、丑闻或二皇子党打压成功时减少。"
      ],
      "military_strength": {
        "direct_control_troops": "35,000人",
        "composition": [
          "萧家私军: 8,000人（精锐）",
          "皇城禁卫军: 12,000人（萧远山影响）",
          "边境驻军: 15,000人（萧家系将领）"
        ],
        "equipment_level": "精良（萧家财力支撑）",
        "loyalty": "85%（基于萧家威望）",
        "military_rating": "A-（质量高但数量有限）"
      },
      "reputation_prestige": {
        "court_support": "45%",
        "folk_prestige": "70%（太子仁政形象）",
        "core_supporters": [
          "礼部尚书孙博文（传统正统派）",
          "兵马大元帅萧远山",
          "太子妃萧暮雪（联姻纽带）"
        ],
        "reputation_rating": "A（正统优势明显）"
      }
    },

    "second_prince_faction": {
      "$meta": {"extensible": false, "required": ["influence", "military_strength", "reputation_prestige"]},
      "influence": [
        110,
        "【二皇子党影响力】范围[0, 200]。当二皇子获得朝臣支持、打压太子党时增加；反之则减少，当太子被识别女儿身且公布于众直接胜利"
      ],
      "military_strength": {
        "direct_control_troops": "28,000人",
        "composition": [
          "二皇子私军: 5,000人（新募精锐）",
          "城防军部分: 8,000人（张德海安插）",
          "地方军阀: 15,000人（利益收买）"
        ],
        "equipment_level": "良好（资金优势采购）",
        "loyalty": "70%（多为利益驱动）",
        "military_rating": "B+（数量可观但忠诚度不稳）"
      },
      "reputation_prestige": {
        "court_support": "55%",
        "folk_prestige": "45%（年轻有为但争议较大）",
        "core_supporters": [
          "吏部尚书张德海（人事大权）",
          "工部尚书张文杰（工程利益）",
          "兵部尚书郑国峰（暗中投靠）",
          "淑妃林芷柔（后宫影响）"
        ],
        "reputation_rating": "B+（实力强但正统性不足）"
      }
    }
  },

  "plot_mechanics": {
    "rules": [
      "派系影响力数值实时影响剧情发展方向",
      "角色行为必须符合其性格设定和政治立场",
      "重大事件发生时自动触发影响力数值调整"
    ],
    "dynamic_event_triggers": [
      "太子党影响力 < 80: 二皇子派加大探查力度",
      "二皇子党影响力 > 120: 淑妃派开始实施激进计划",
      "两派差值 > 30: 弱势方采取紧急措施"
    ],
    "narrative_management": {
      "plot_line_binding": "派系影响力系统与剧情线深度绑定",
      "mutual_exclusion": "剧情线互斥机制，避免过多同时发生",
      "cooldown": "剧情冷却时间，保证游戏节奏",
      "chain_reaction": "剧情后果的连锁反应系统"
    }
  }
}

